},{"lat":42.623025,"lng":1.553125,"ele":1856.8},{"lat":42.62307,"lng":1.55312,"ele":1856.5},{"lat":42.623114,"lng":1.553105,"ele":1855},{"lat":42.623072,"lng":1.553065,"ele":1851.6},{"lat":42.623026,"lng":1.553034,"ele":1850.6},{"lat":42.622983,"lng":1.553002,"ele":1850.4},{"lat":42.622946,"lng":1.552965,"ele":1848.3},{"lat":42.622904,"lng":1.552923,"ele":1849},{"lat":42.622948,"lng":1.552907,"ele":1847.1},{"lat":42.622994,"lng":1.552889,"ele":1845},{"lat":42.623037,"lng":1.552871,"ele":1844.4},{"lat":42.623076,"lng":1.55284,"ele":1843},{"lat":42.623048,"lng":1.55279,"ele":1841.2},{"lat":42.623038,"lng":1.552725,"ele":1839.5},{"lat":42.623073,"lng":1.552683,"ele":1837.8},{"lat":42.623098,"lng":1.552629,"ele":1835.3},{"lat":42.623101,"lng":1.552565,"ele":1833.8},{"lat":42.623121,"lng":1.552504,"ele":1830.9},{"lat":42.623164,"lng":1.552464,"ele":1829.6},{"lat":42.623203,"lng":1.55243,"ele":1827.6},{"lat":42.623238,"lng":1.552388,"ele":1827},{"lat":42.62326,"lng":1.552327,"ele":1825.9},{"lat":42.623281,"lng":1.552266,"ele":1823.9},{"lat":42.623312,"lng":1.552219,"ele":1820.6},{"lat":42.623355,"lng":1.552181,"ele":1818},{"lat":42.623397,"lng":1.552131,"ele":1816.1},{"lat":42.623439,"lng":1.5521,"ele":1816.2},{"lat":42.62346,"lng":1.552041,"ele":1813.1},{"lat":42.623478,"lng":1.551982,"ele":1809.1},{"lat":42.623455,"lng":1.551924,"ele":1808},{"lat":42.623418,"lng":1.551874,"ele":1805.2},{"lat":42.623372,"lng":1.551862,"ele":1807.2},{"lat":42.623324,"lng":1.551857,"ele":1806.7},{"lat":42.623288,"lng":1.551805,"ele":1804.2},{"lat":42.623332,"lng":1.551772,"ele":1803.1},{"lat":42.623396,"lng":1.551768,"ele":1802.7},{"lat":42.623452,"lng":1.551769,"ele":1802.4},{"lat":42.623498,"lng":1.551779,"ele":1802.1},{"lat":42.62355,"lng":1.551788,"ele":1801.9},{"lat":42.623595,"lng":1.551797,"ele":1801.6},{"lat":42.623654,"lng":1.551799,"ele":1801.1},{"lat":42.623705,"lng":1.551808,"ele":1800.8},{"lat":42.623751,"lng":1.551808,"ele":1800.4},{"lat":42.623802,"lng":1.551805,"ele":1800}]